/**
 * SLICE 156 — the declared-route table, read from the router itself.
 *
 * `routeTree.gen.ts` is generated by the TanStack Router plugin at build and
 * dev time and is git-ignored, so the route paths are NOT copied by hand here
 * (a hand-copied list is exactly what rots: it 404s a real page the day someone
 * adds a route). Instead this module instantiates the same router the app uses
 * and reads `routesByPath` — the router's own answer to "which paths exist".
 *
 * Loaded LAZILY and cached: prod-server.ts already preloads `entry-server`,
 * which imports the same tree, so the module graph is warm by the time the
 * first unknown path arrives, and a server that never sees one never pays for
 * it.
 *
 * FAIL-OPEN, LOUDLY: if the tree cannot be loaded (a tree where the generator
 * never ran) this returns an empty table and the caller keeps the old SPA
 * behaviour rather than 404-ing the whole site. That case is logged by the
 * caller — it means the build is broken, not that the pages are gone.
 */
import { compileRoutePatterns } from "./route-match";

/** Cached promise so concurrent requests share one load. */
let patternsPromise: Promise<RegExp[]> | null = null;
/** Cached declared paths (for tests and diagnostics). */
let pathsPromise: Promise<string[]> | null = null;

/**
 * Load the router's declared page paths (e.g. `/pricing`, `/portal/$id`).
 * Returns [] when the route tree is unavailable — never throws.
 */
export async function loadDeclaredRoutePaths(): Promise<string[]> {
  if (!pathsPromise) {
    pathsPromise = (async () => {
      try {
        const [{ createRouter, createMemoryHistory }, { routeTree }] = await Promise.all([
          import("@tanstack/react-router"),
          import("../routeTree.gen"),
        ]);
        const router = createRouter({
          routeTree: routeTree as any,
          history: createMemoryHistory({ initialEntries: ["/"] }),
        });
        const byPath = (router as any).routesByPath as Record<string, unknown> | undefined;
        return byPath ? Object.keys(byPath) : [];
      } catch (err: any) {
        console.log(
          "[route-table] declared route table unavailable — SPA fallback keeps its old behaviour:",
          err?.message || String(err),
        );
        return [];
      }
    })();
  }
  return pathsPromise;
}

/**
 * Load the compiled matchers for every declared route. Empty array means the
 * table is unavailable; callers must treat that as "cannot tell" (fail open).
 */
export async function loadDeclaredRoutePatterns(): Promise<RegExp[]> {
  if (!patternsPromise) {
    patternsPromise = (async () => compileRoutePatterns(await loadDeclaredRoutePaths()))();
  }
  return patternsPromise;
}

/** Test-only: forget the cached table so a test can prove a cold load. */
export function __resetRouteTableForTest(): void {
  pathsPromise = null;
  patternsPromise = null;
}
